import * as core from './comparing-orders-core.mjs';
import {comparisonModes,comparisonSource} from './comparing-orders-content.mjs';
import {hearButton} from './play-media.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fill=(s,key,values={})=>esc(s.text[key].replace(/\{([A-Za-z]+)\}/g,(_,k)=>Object.hasOwn(values,k)?String(values[k]):`{${k}}`));
const btn=(label,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const textForChoice=(mode,code)=>`${mode}${code[0].toUpperCase()}${code.slice(1)}`;
const modeName=mode=>mode==='compare'?'comparison':'return';
const marks=(n,origin,paired=false)=>Array.from({length:n},()=>`<span class="comparison-mark ${paired?'is-paired':''}" data-comparison-counter data-origin="${origin}" aria-hidden="true"></span>`).join('');
const ten=(origin,paired=false)=>`<span class="comparison-ten ${paired?'is-paired':''}" data-comparison-ten aria-label="one ten${paired?' matched':''}">${marks(10,origin,paired)}</span>`;
function crate(label,tens,ones,origin,pairedTens=0,pairedOnes=0){return `<section class="comparison-crate comparison-${origin}" aria-label="${esc(label)}"><h3>${esc(label)}</h3><div class="comparison-mark-row">${Array.from({length:tens},(_,i)=>ten(origin,i<pairedTens)).join('')}${marks(pairedOnes,origin,true)}${marks(ones-pairedOnes,origin)}</div></section>`;}
function picture(w,mode,s){const m=w.model;
 if(mode==='compare'){const paired=core.modelCount(mode,m),values={paired,extra:23-paired,dotLeft:11-paired};return `<section class="comparison-picture" id="comparison-picture" tabindex="-1"><h2>${fill(s,'compareTitle')}</h2><p>${fill(s,'compareSource')}</p><div class="comparison-panels">${crate(s.text.pipCrate,2,3,'pip',m.pairedTens,m.pairedOnes)}${crate(s.text.dotCrate,1,1,'dot',m.pairedTens,m.pairedOnes)}</div><p data-comparison-model-status>${fill(s,'compareStatus',values)}</p></section>`;}
 const t=2-m.storeTens,o=3-m.storeOnes,values={tableTens:t,tableOnes:o,table:10*t+o,storeTens:m.storeTens,storeOnes:m.storeOnes,store:10*m.storeTens+m.storeOnes};
 return `<section class="comparison-picture" id="comparison-picture" tabindex="-1"><h2>${fill(s,'returnTitle')}</h2><p>${fill(s,'returnSource')}</p><div class="comparison-panels">${crate(s.text.pipTable,t,o,'pip')}${crate(s.text.storeTray,m.storeTens,m.storeOnes,'store')}</div><p data-comparison-model-status>${fill(s,'returnStatus',values)}</p></section>`;
}
const actionKeys={compare:[['add-ten','matchTen'],['undo-ten','undoTen'],['add-one','matchOne'],['undo-one','undoOne'],['reset','resetCompare']],return:[['add-ten','returnTen'],['undo-ten','bringTen'],['add-one','returnOne'],['undo-one','bringOne'],['reset','resetReturn']]};
function actions(w,mode,s){const m=w.model,tenCount=mode==='compare'?m.pairedTens:m.storeTens,oneCount=mode==='compare'?m.pairedOnes:m.storeOnes;return `<section class="comparison-actions" aria-label="Change the ${modeName(mode)} picture">${actionKeys[mode].map(([action,key])=>btn(s.text[key],`data-comparison-action="${action}" ${action==='add-ten'&&tenCount||action==='undo-ten'&&!tenCount||action==='add-one'&&oneCount||action==='undo-one'&&!oneCount?'disabled':''}`)).join('')}</section>`;}
function checkText(h,current=false,model=null){const s=h.source,mode=h.mode,earlier=model&&JSON.stringify(model)!==JSON.stringify(h.model);return `<section class="comparison-check"><p>${fill(s,current?'currentCheck':'earlierCheck')}: ${esc(h.raw)}. ${fill(s,h.numberMatches?'numberMatch':'numberDifferent')}</p><p>${fill(s,h.meaningMatches?'meaningMatch':'meaningDifferent')} ${fill(s,mode==='compare'?'compareMeaning':'returnMeaning')}</p>${earlier?`<p><strong>${fill(s,'earlier')}:</strong> ${mode==='compare'?`matched ${core.modelCount(mode,h.model)}; current picture matched ${core.modelCount(mode,model)}`:`store ${core.modelCount(mode,h.model)}; current store ${core.modelCount(mode,model)}`}.</p>`:''}<p>${earlier?`At this earlier check: `:''}${fill(s,mode==='compare'?(h.modelComplete?'compareComplete':'compareIncomplete'):(h.modelComplete?'returnComplete':'returnIncomplete'))}</p>${h.priorHistoryUnknown?'<p class="tiny">Earlier encounters before recovery are unknown.</p>':''}</section>`;}
function response(w,mode,s){const choices=s.choiceOrder[mode].map(code=>`<label class="comparison-choice"><input type="radio" name="comparison-meaning" value="${code}" data-comparison-meaning ${w.meaningChoice===code?'checked':''}><span>${fill(s,textForChoice(mode,code))}</span></label>`).join(''),indices=core.readableChecks(w,mode),h=w.currentFeedback===null?null:w.checks[w.currentFeedback],current=h&&core.validComparisonCheck(h,mode)&&w.currentFeedback===indices.at(-1)&&h.raw===w.raw&&h.meaningChoice===w.meaningChoice?h:null,kept=w.kept===null?null:core.validComparisonKept(w.kept,mode)?w.kept:false;
 return `<section class="comparison-response"><h2 id="comparison-answer-title" tabindex="-1">${fill(s,'answerTitle')}</h2><p class="comparison-equation">23 − 11 = ?</p><form data-comparison-form><label for="comparison-number">${fill(s,'numberLabel')}</label><input id="comparison-number" data-comparison-raw type="text" inputmode="numeric" maxlength="24" autocomplete="off" spellcheck="false" value="${esc(w.raw)}" ${w.error?'aria-invalid="true"':''}><fieldset><legend>${fill(s,'meaningLabel')}</legend>${choices}</fieldset>${w.error?`<p id="comparison-error" role="alert" tabindex="-1">${fill(s,'syntax')}</p>`:''}<div class="comparison-response-actions"><button class="primary" type="submit">${fill(s,'check')}</button>${btn(s.text[kept?'replace':'keep'],`data-comparison-keep ${kept===false?'disabled aria-describedby="comparison-kept-unavailable"':''}`)}</div></form>${indices.length>=8?`<p class="tiny" data-comparison-cap>${fill(s,'cap')}</p>`:''}${current?`<div id="comparison-feedback" role="status" tabindex="-1">${checkText(current,true,w.model)}</div>`:''}<p id="comparison-kept-status" role="status" tabindex="-1">${kept?fill(s,'keptNotice'):''}</p>${kept===false?'<p id="comparison-kept-unavailable">One earlier kept copy cannot be read here, so this question cannot replace it. The original stays in your notes. Download notes or use a separate explorer for a new kept copy.</p>':''}<details data-comparison-replace hidden><summary>${fill(s,'replace')}</summary><p>${fill(s,'replacePrompt')}</p><p><a href="#notes">Download notes first</a></p>${btn(s.text.replaceConfirm,'data-comparison-confirm',true)}${btn(s.text.cancel,'data-comparison-cancel')}</details><details class="comparison-history"><summary>${fill(s,'history')} (${indices.length} readable checks)</summary>${w.checks.map((h,i)=>core.validComparisonCheck(h,mode)?checkText(h):`<p>Earlier check ${i+1} is unavailable. Its original data remains in the notes download.</p>`).join('')}${kept?`<section><h3>${fill(kept.source,'keptTitle')}</h3><p>${fill(kept.source,mode==='compare'?'comparePrompt':'returnPrompt')}</p><p>Typed number: ${esc(kept.raw||'(blank)')}. Chosen meaning: ${kept.meaningChoice?fill(kept.source,textForChoice(mode,kept.meaningChoice)):'(none)'}. ${mode==='compare'?'Matched':'Store tray'}: ${core.modelCount(mode,kept.model)}.</p>${kept.latestCheck?checkText(kept.latestCheck):'<p>No number-and-meaning check in this copy.</p>'}</section>`:''}</details></section>`;
}
function unavailable(){return `<section class="comparison-orders"><a href="#numbers">Back to Number Garden</a><h1>Comparing supply orders</h1><p>This saved work uses a format this version cannot play. Its original data is retained unchanged.</p><p><a href="#notes">Visit grown-up notes and download a copy</a></p><details><summary>Start fresh and keep the original</summary><p>Check your download first if you want another copy.</p>${btn('Confirm fresh start and keep the old record','data-comparison-recover',true)}</details><p id="comparison-status" role="status" tabindex="-1"></p></section>`;}
function chooser(s,started=false){return `<section class="comparison-orders comparison-chooser"><a href="#numbers">Back to Number Garden</a><h1>${fill(s,'entryTitle')}</h1><p>${fill(s,'entryIntro')}</p><p>${fill(s,'chooseCompare')}</p><p>${fill(s,'chooseReturn')}</p>${started?'<p>Your two pictures are waiting below.</p>':btn(s.text.start,'data-comparison-start',true)}<p id="comparison-status" role="status" tabindex="-1"></p></section>`;}
export function comparisonEntry(){return `<section class="panel comparison-entry"><h2>Comparing supply orders</h2><p>Match two crates, then see how returning counters asks a different question with the same numbers.</p><a class="secondary" href="#numbers/compare">Try both questions</a></section>`;}
export function renderComparison(state,detail=''){
 const v=core.comparisonView(state);if(v.unavailable)return {html:unavailable(),examples:[]};
 const s=v.root?.source||comparisonSource();
 if(v.absent)return {html:chooser(s),examples:[]};
 if(detail==='choose')return {html:chooser(s,true),examples:[]};
 if(!v.work)return {html:`<section class="comparison-orders"><a href="#numbers">Back to Number Garden</a><h1>${fill(s,'entryTitle')}</h1><p>This picture cannot be read. Its original record remains in your notes.</p><p><a href="#notes">Download notes</a></p>${comparisonModes.filter(x=>x!==v.mode&&core.validComparisonMode(v.root.modes[x],x)).map(x=>btn(`Open the ${modeName(x)} picture`,`data-comparison-switch="${x}"`)).join('')}<details><summary>Start fresh and keep the original</summary><p>Check your download first if you want another copy.</p>${btn('Confirm fresh start and keep the old record','data-comparison-recover',true)}</details><p id="comparison-status" role="status" tabindex="-1"></p></section>`,examples:[]};
 const {root,mode,work:w}=v,page=root.page==='answer'?'answer':'picture';
 const turn=page==='picture'?`${picture(w,mode,s)}${actions(w,mode,s)}<p class="comparison-turn-nav">${btn(s.text.nextTurn,'data-comparison-page="answer"',true)}</p>`:`${response(w,mode,s)}<details class="comparison-help" data-comparison-help><summary>${fill(s,'helpTitle')}</summary><p>${fill(s,'helpBody')}</p><p>${fill(s,'talk')}</p>${btn(s.text.together,'data-comparison-together')}<p id="comparison-together-status" role="status"></p></details><p class="comparison-turn-nav">${btn(s.text.backTurn,'data-comparison-page="picture"')}</p>`;
 return {html:`<section class="comparison-orders" data-comparison-root><a href="#numbers">Back to Number Garden</a><header><h1>${fill(s,'entryTitle')}</h1><p>${fill(s,'entryIntro')}</p><p>${fill(s,mode==='compare'?'comparePrompt':'returnPrompt')}</p>${hearButton(s.text[mode==='compare'?'comparePrompt':'returnPrompt'],s.text.hear)}</header>${turn}<p>${btn(s.text.other,`data-comparison-switch="${mode==='compare'?'return':'compare'}"`)}</p><p id="comparison-status" role="status" tabindex="-1"></p></section>`,examples:page==='picture'?core.comparisonDisplaySignatures(root):[]};
}
export function comparisonNotes(state){if(!Object.hasOwn(state,'comparisonSupplies'))return '';const v=core.comparisonView(state);if(v.unavailable)return `<section class="panel"><h2>Comparing Supply Orders</h2><p>Unsupported saved work retained unchanged.</p><pre>${esc(JSON.stringify(state.comparisonSupplies,null,2))}</pre></section>`;return `<details class="panel"><summary>Comparing Supply Orders: two pictured subtraction meanings</summary><p>Entered numbers, chosen meaning labels and pictured actions are separate. They do not establish independent subtraction or mastery.</p>${comparisonModes.map(mode=>{const w=v.root.modes[mode];return core.validComparisonMode(w,mode)?`<section><h3>${fill(v.root.source,mode==='compare'?'compareTitle':'returnTitle')}</h3><p>Picture ${core.modelComplete(mode,w.model)?'complete':'in progress'}; entered number ${esc(w.raw||'(blank)')}; meaning ${esc(w.meaningChoice||'(none)')}. ${core.readableChecks(w,mode).length} readable checks.</p><details><summary>Frozen source, checks, kept copy and unavailable rows</summary><pre>${esc(JSON.stringify(w,null,2))}</pre></details></section>`:`<section><h3>${esc(mode)}</h3><p>This picture is unavailable; the original record is retained.</p><pre>${esc(JSON.stringify(w,null,2))}</pre></section>`;}).join('')}${Object.hasOwn(v.root,'retainedRaw')?`<details><summary>Original recovered record</summary><pre>${esc(JSON.stringify(v.root.retainedRaw,null,2))}</pre></details>`:''}<a href="#numbers/compare">Visit Comparing Supply Orders</a></details>`;}

function adoptCandidate(state,candidate){state.comparisonSupplies=candidate.comparisonSupplies;for(const [key,draft] of Object.entries(candidate.broad?.drafts||{})){const original=state.broad?.drafts?.[key];if(!original||!draft)continue;for(const flag of ['familiar','priorExposureUnknown'])if(draft[flag]&&!original[flag])original[flag]=true;}}
export function commitComparison(state,mutate,{canExport,recordDisplay}={},show=true){
 let candidate;try{candidate=structuredClone(state);}catch{return false;}
 if(mutate&&!mutate(candidate))return false;
 if(show){const root=core.comparisonState(candidate);if(root&&root.page!=='answer'){const examples=core.comparisonDisplaySignatures(root);recordDisplay?.(candidate,examples);}}
 if(!canExport?.(candidate))return false;
 adoptCandidate(state,candidate);return true;
}
export function preflightComparisonDisplay(state,examples,{canExport,recordDisplay}={}){const root=core.comparisonState(state);if(!root||!examples.some(s=>!root.shownBundleExamples.includes(s)))return true;return commitComparison(state,null,{canExport,recordDisplay},true);}
export function comparisonExposureNotice(){return `<section class="comparison-orders" role="status"><a href="#numbers">Back to Number Garden</a><h1>Comparing supply orders</h1><p>This picture would make the notes too large to import. The earlier work is unchanged. Download your notes or use a separate explorer before showing it.</p><p><a href="#notes">Visit grown-up notes and download a copy</a></p></section>`;}

export function bindComparison(state,{save,render,focus,canExport,recordDisplay}={}){
 const scope=document.querySelector('.comparison-orders');if(!scope)return;let rootRef=state.comparisonSupplies,mode=core.comparisonView(state).mode,replaceRoot=null,used=false;
 const live=()=>scope.isConnected&&state.comparisonSupplies===rootRef&&core.comparisonView(state).mode===mode;
 const target=selector=>focus?.(selector)||document.querySelector(selector)?.focus();
 const refuse=()=>{const p=scope.querySelector('#comparison-status');if(p){p.textContent='This change would make the notes too large to import, or this picture has changed. Your earlier work is unchanged. Download notes or use a separate explorer.';p.focus();}};
 const transact=(fn,{rerender=true,where=null,show=true}={})=>{if(!live())return false;if(!commitComparison(state,fn,{canExport,recordDisplay},show)){refuse();return false;}rootRef=state.comparisonSupplies;save?.();if(rerender){render?.();if(where)target(where);}return true;};
 scope.querySelector('[data-comparison-start]')?.addEventListener('click',()=>{if(!live())return;transact(core.startComparison,{where:'#comparison-picture'});});
 scope.querySelector('[data-comparison-recover]')?.addEventListener('click',()=>{if(!live()||!window.confirm('Start fresh while keeping the complete original record in your notes?'))return;transact(core.recoverComparison,{where:'#comparison-picture'});});
 scope.querySelectorAll('[data-comparison-switch]').forEach(b=>b.onclick=()=>{if(!live())return;transact(c=>core.switchComparison(c,b.dataset.comparisonSwitch),{where:'#comparison-picture'});});
 scope.querySelectorAll('[data-comparison-page]').forEach(b=>b.onclick=()=>{if(!live())return;const page=b.dataset.comparisonPage;transact(c=>core.setComparisonPage(c,page),{where:page==='picture'?'#comparison-picture':'#comparison-answer-title'});});
 scope.querySelectorAll('[data-comparison-action]').forEach(b=>b.onclick=()=>{if(!live())return;const action=b.dataset.comparisonAction;if(transact(c=>core.moveComparison(c,action),{where:null})){const fresh=document.querySelector(`[data-comparison-action="${action}"]`);target(fresh&&!fresh.disabled?`[data-comparison-action="${action}"]`:'#comparison-picture');}});
 scope.querySelector('[data-comparison-raw]')?.addEventListener('input',e=>{if(!live())return;const old=core.comparisonView(state).work.raw;if(transact(c=>core.setComparisonRaw(c,e.target.value),{rerender:false})){scope.querySelector('#comparison-feedback')?.remove();scope.querySelector('#comparison-error')?.remove();e.target.removeAttribute('aria-invalid');}else e.target.value=old;});
 scope.querySelectorAll('[data-comparison-meaning]').forEach(b=>b.addEventListener('change',()=>{if(!live())return;const old=core.comparisonView(state).work.meaningChoice;if(transact(c=>core.selectComparisonMeaning(c,b.value),{rerender:false})){scope.querySelector('#comparison-feedback')?.remove();scope.querySelector('#comparison-error')?.remove();}else scope.querySelectorAll('[data-comparison-meaning]').forEach(x=>x.checked=x.value===old);}));
 scope.querySelector('[data-comparison-form]')?.addEventListener('submit',e=>{e.preventDefault();if(!live())return;const w=core.comparisonView(state).work,n=core.readableChecks(w,mode).length;if(n>8&&!window.confirm('Replace this question\'s oldest readable check? Download notes first if you want it.'))return;if(!live())return;transact(c=>core.checkComparison(c,n>8),{where:core.parseComparisonNumber(w.raw)===null||w.meaningChoice===null?'#comparison-error':'#comparison-feedback'});});
 scope.querySelector('[data-comparison-keep]')?.addEventListener('click',()=>{if(!live())return;const w=core.comparisonView(state).work;if(w.kept===null){transact(c=>core.keepComparison(c),{where:'#comparison-kept-status'});return;}if(!core.validComparisonKept(w.kept,mode)){refuse();return;}const d=scope.querySelector('[data-comparison-replace]');replaceRoot=state.comparisonSupplies;used=false;d.hidden=false;d.open=true;target('[data-comparison-confirm]');});
 const replace=scope.querySelector('[data-comparison-replace]');replace?.addEventListener('toggle',()=>{if(!replace.open)used=true;});
 scope.querySelector('[data-comparison-cancel]')?.addEventListener('click',()=>{used=true;replace.open=false;replace.hidden=true;target('[data-comparison-keep]');});
 scope.querySelector('[data-comparison-confirm]')?.addEventListener('click',()=>{if(!live()||used||!replace.open||replace.hidden||replaceRoot!==state.comparisonSupplies)return;used=true;transact(c=>core.keepComparison(c,true),{where:'#comparison-kept-status'});});
 scope.querySelector('[data-comparison-help] summary')?.addEventListener('click',e=>{const d=e.currentTarget.parentElement;if(d.open)return;e.preventDefault();if(transact(c=>core.useComparisonSupport(c,'help'),{rerender:false})){d.open=true;}});
 scope.querySelector('[data-comparison-together]')?.addEventListener('click',()=>{if(transact(c=>core.useComparisonSupport(c,'together'),{rerender:false})){const p=scope.querySelector('#comparison-together-status');p.textContent='Talk through this picture together. Nothing moved or answered automatically.';}});
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live()||!transact(c=>core.useComparisonSupport(c,'narrationRequested'),{rerender:false})){e.preventDefault();e.stopImmediatePropagation();}},{capture:true}));
}
